def affected(l) -> bool:
    # Original returns True only for a non-empty run of consecutive integers.
    # Mutant range(min, max) never contains max, so for non-empty l it is always False.
    # Empty input raises ValueError in both versions, so it is not a difference.
    if not l:
        return False
    return len(set(l)) == len(l) and max(l) - min(l) + 1 == len(l)
